/* ============================================
   ClipCast — Global Styles
   ============================================ */

:root {
  --primary: #1868DB;
  --primary-dark: #1457b8;
  --accent: #FF613D;
  --accent-dark: #e55533;
  --dark: #292A2E;
  --gray-50: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1E293B;
  --white: #ffffff;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 60px rgba(0,0,0,0.16);
  --max-width: 1200px;
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  border: none;
  transition: var(--transition);
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }

.btn-accent {
  background: var(--accent);
  color: var(--white);
}
.btn-accent:hover { background: var(--accent-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 1.5px solid var(--gray-300);
}
.btn-outline:hover { border-color: var(--primary); color: var(--primary); }

.btn-ghost {
  background: transparent;
  color: var(--primary);
}
.btn-ghost:hover { background: rgba(24,104,219,0.08); }

.btn-white {
  background: var(--white);
  color: var(--primary);
}
.btn-white:hover { background: var(--gray-100); }

/* Navbar */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  font-size: 22px;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-700);
  transition: var(--transition);
}
.nav-links a:hover { color: var(--primary); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Hero */
.hero {
  position: relative;
  padding: 80px 0 100px;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #f0f7ff 0%, #fff 50%, #fff5f2 100%);
  z-index: -1;
}

.hero-content {
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
}

.hero h1 {
  font-size: clamp(36px, 5vw, 56px);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
}

.hero p {
  font-size: 18px;
  color: var(--gray-600);
  margin-bottom: 32px;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.hero-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Logo bar */
.logo-bar {
  padding: 40px 0;
  border-top: 1px solid var(--gray-200);
  border-bottom: 1px solid var(--gray-200);
  background: var(--gray-50);
}

.logo-bar p {
  text-align: center;
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 20px;
}

.logo-list {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 40px;
  flex-wrap: wrap;
}

.logo-item {
  font-size: 18px;
  font-weight: 700;
  color: var(--gray-400);
  opacity: 0.7;
}

/* Sections */
.section {
  padding: 80px 0;
}

.section-alt { background: var(--gray-50); }

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-header h2 {
  font-size: clamp(28px, 3.5vw, 40px);
  font-weight: 800;
  line-height: 1.15;
  margin-bottom: 16px;
}

.section-header p {
  font-size: 17px;
  color: var(--gray-600);
}

/* Feature cards */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: var(--gray-300);
}

.feature-card .icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--primary), #4a9eff);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 22px;
  margin-bottom: 20px;
}

.feature-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 10px;
}

.feature-card p {
  font-size: 14px;
  color: var(--gray-600);
  line-height: 1.6;
}

/* Two column layout */
.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

@media (max-width: 768px) {
  .two-col { grid-template-columns: 1fr; gap: 40px; }
  .nav-links { display: none; }
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item h3 {
  font-size: 48px;
  font-weight: 800;
  color: var(--primary);
  line-height: 1;
}

.stat-item p {
  font-size: 15px;
  color: var(--gray-600);
  margin-top: 8px;
}

/* Testimonials */
.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--gray-200);
}

.testimonial-card p {
  font-size: 15px;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 20px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-author .avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 14px;
}

.testimonial-author .name {
  font-weight: 700;
  font-size: 14px;
}

.testimonial-author .role {
  font-size: 13px;
  color: var(--gray-500);
}

/* Pricing */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 40px;
}

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 14px;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active { background: var(--primary); }

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after { left: 27px; }

.toggle-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-600);
}

.toggle-label.active { color: var(--dark); }

.save-badge {
  display: inline-block;
  background: var(--accent);
  color: var(--white);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  margin-left: 8px;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

@media (max-width: 1024px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  .pricing-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  border: 1px solid var(--gray-200);
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover { box-shadow: var(--shadow-lg); }

.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary);
}

.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 11px;
  font-weight: 700;
  padding: 5px 14px;
  border-radius: 20px;
}

.pricing-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 36px;
  font-weight: 800;
  margin-bottom: 4px;
}

.pricing-card .price span {
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-card .desc {
  font-size: 13px;
  color: var(--gray-500);
  margin-bottom: 20px;
  min-height: 40px;
}

.pricing-card ul {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-card ul li {
  font-size: 13px;
  color: var(--gray-600);
  padding: 6px 0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.pricing-card ul li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
  flex-shrink: 0;
}

/* Comparison table */
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 40px;
  font-size: 14px;
}

.comparison-table th,
.comparison-table td {
  padding: 14px 16px;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.comparison-table th {
  font-weight: 700;
  color: var(--gray-700);
  background: var(--gray-50);
}

.comparison-table td:first-child {
  font-weight: 500;
  color: var(--gray-700);
}

.comparison-table td {
  color: var(--gray-600);
}

.comparison-table .check {
  color: var(--primary);
  font-weight: 700;
}

.comparison-table .dash {
  color: var(--gray-400);
}

/* FAQ */
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--dark);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
}

.faq-question:hover { color: var(--primary); }

.faq-question .icon {
  font-size: 20px;
  transition: var(--transition);
  color: var(--gray-400);
}

.faq-item.open .faq-question .icon { transform: rotate(45deg); color: var(--primary); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer p {
  padding-bottom: 20px;
  font-size: 14px;
  color: var(--gray-600);
  line-height: 1.7;
}

/* CTA Banner */
.cta-banner {
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--primary) 0%, #0d4a9e 100%);
  z-index: -1;
}

.cta-banner h2 {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  font-size: 17px;
  color: rgba(255,255,255,0.8);
  margin-bottom: 28px;
}

/* Footer */
.footer {
  background: var(--dark);
  color: var(--gray-300);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 640px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

.footer-brand {
  font-size: 20px;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col ul li a {
  font-size: 13px;
  color: var(--gray-400);
  transition: var(--transition);
}

.footer-col ul li a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--gray-500);
}

/* Cookie banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  border-top: 1px solid var(--gray-200);
  padding: 20px 24px;
  z-index: 200;
  box-shadow: var(--shadow-lg);
  display: none;
}

.cookie-banner.show { display: block; }

.cookie-banner .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-banner p {
  font-size: 13px;
  color: var(--gray-600);
  flex: 1;
}

.cookie-actions {
  display: flex;
  gap: 10px;
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 300;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.modal-overlay.show { display: flex; }

.modal {
  background: var(--white);
  border-radius: var(--radius-lg);
  max-width: 480px;
  width: 100%;
  padding: 32px;
  box-shadow: var(--shadow-xl);
}

.modal h3 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 8px;
}

.modal p {
  font-size: 14px;
  color: var(--gray-600);
  margin-bottom: 24px;
}

.modal-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid var(--gray-100);
}

.modal-row:last-child { border-bottom: none; }

.modal-row .label {
  font-weight: 600;
  font-size: 14px;
}

.modal-row .desc {
  font-size: 12px;
  color: var(--gray-500);
}

/* Toggle switch small */
.toggle-sm {
  width: 40px;
  height: 22px;
  background: var(--gray-300);
  border-radius: 11px;
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-sm.active { background: var(--primary); }

.toggle-sm::after {
  content: '';
  position: absolute;
  width: 18px;
  height: 18px;
  background: var(--white);
  border-radius: 50%;
  top: 2px;
  left: 2px;
  transition: var(--transition);
}

.toggle-sm.active::after { left: 20px; }

/* Auth pages */
.auth-page {
  min-height: 100vh;
  display: flex;
}

.auth-left {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 48px 24px;
}

.auth-right {
  flex: 1;
  background: linear-gradient(135deg, var(--primary), #0d4a9e);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 48px;
  color: var(--white);
}

@media (max-width: 768px) {
  .auth-page { flex-direction: column; }
  .auth-right { display: none; }
}

.auth-box {
  max-width: 400px;
  width: 100%;
}

.auth-box h1 {
  font-size: 28px;
  font-weight: 800;
  margin-bottom: 8px;
}

.auth-box .subtitle {
  font-size: 15px;
  color: var(--gray-500);
  margin-bottom: 28px;
}

.social-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  background: var(--white);
  font-size: 14px;
  font-weight: 600;
  color: var(--dark);
  cursor: pointer;
  margin-bottom: 10px;
  transition: var(--transition);
}

.social-btn:hover { background: var(--gray-50); border-color: var(--gray-300); }

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 20px 0;
  color: var(--gray-400);
  font-size: 13px;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.input-field {
  width: 100%;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  border: 1.5px solid var(--gray-200);
  font-size: 15px;
  outline: none;
  transition: var(--transition);
  margin-bottom: 12px;
}

.input-field:focus { border-color: var(--primary); }

.auth-footer {
  font-size: 12px;
  color: var(--gray-500);
  text-align: center;
  margin-top: 20px;
}

.auth-footer a { color: var(--primary); font-weight: 600; }

/* Team size slider */
.slider-wrap {
  max-width: 400px;
  margin: 0 auto 40px;
  text-align: center;
}

.slider-wrap label {
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-700);
  display: block;
  margin-bottom: 12px;
}

.team-slider {
  width: 100%;
  -webkit-appearance: none;
  height: 6px;
  border-radius: 3px;
  background: var(--gray-200);
  outline: none;
}

.team-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  box-shadow: var(--shadow-sm);
}

.team-slider::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  border: none;
}

/* Use case cards */
.usecase-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

@media (max-width: 1024px) {
  .usecase-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  .usecase-grid { grid-template-columns: 1fr; }
}

.usecase-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.usecase-card:hover { box-shadow: var(--shadow-md); border-color: var(--primary); }

.usecase-card .icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: rgba(24,104,219,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  font-size: 20px;
  margin-bottom: 16px;
}

.usecase-card h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 8px;
}

.usecase-card p {
  font-size: 14px;
  color: var(--gray-600);
}

/* Blog cards */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

@media (max-width: 640px) {
  .blog-grid { grid-template-columns: 1fr; }
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
